:root {
  color-scheme: light;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  color: #24332d;
  background: #d9ebd9;
  font-size: 16px;
}

* { box-sizing: border-box; }
body {
  min-width: 360px;
  min-height: 100vh;
  margin: 0;
  padding: 24px 16px;
  display: grid;
  place-items: center;
  background: radial-gradient(circle at 50% 20%, #eff8df, #c6e2d0 75%);
}
.game-card {
  width: min(100%, 480px);
  padding: clamp(22px, 6vw, 38px);
  border: 3px solid #24332d;
  border-radius: 20px;
  background: #fffdf2;
  box-shadow: 8px 8px 0 #24332d;
  text-align: center;
}
.eyebrow { margin: 0 0 8px; color: #457a59; font-size: 0.85rem; font-weight: 800; letter-spacing: 0.12em; }
h1 { margin: 0; font-size: clamp(2rem, 8vw, 2.8rem); line-height: 1.1; }
.intro { margin: 12px 0 24px; color: #53675a; }
.scoreboard { display: flex; justify-content: center; gap: 44px; margin-bottom: 22px; }
.scoreboard > div { display: grid; gap: 3px; min-width: 84px; }
.stat-label { color: #53675a; font-size: 0.8rem; font-weight: 800; letter-spacing: 0.1em; }
.scoreboard strong { font-size: 2rem; line-height: 1; }
.seconds { margin-left: 2px; color: #53675a; font-size: 1rem; }
.board { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; padding: 14px; border: 3px solid #24332d; border-radius: 16px; background: #b8d99b; }
.hole {
  aspect-ratio: 1;
  min-width: 0;
  overflow: hidden;
  display: grid;
  place-items: center;
  border: 3px solid #24332d;
  border-radius: 50%;
  background: #6d8e53;
  box-shadow: inset 0 7px 0 #587444;
  cursor: pointer;
  touch-action: manipulation;
}
.hole:hover { background: #789b5c; }
.hole:focus-visible, .start-button:focus-visible { outline: 4px solid #e69145; outline-offset: 3px; }
.hole:active { transform: scale(0.96); }
.mole { display: none; color: #f3bd76; font-size: clamp(2.5rem, 11vw, 4rem); line-height: 1; text-shadow: 0 3px 0 #a96542; }
.hole.active .mole { display: block; }
.message { min-height: 1.5em; margin: 19px 0 14px; font-weight: 650; }
.start-button { min-height: 52px; padding: 12px 28px; border: 3px solid #24332d; border-radius: 12px; background: #e69145; color: #24332d; font: inherit; font-weight: 800; cursor: pointer; box-shadow: 0 4px 0 #24332d; }
.start-button:hover { background: #f0a358; }
.start-button:active { transform: translateY(3px); box-shadow: 0 1px 0 #24332d; }
.start-button:disabled { cursor: default; opacity: 0.65; }
@media (max-width: 400px) {
  .board { gap: 8px; padding: 10px; }
  .scoreboard { gap: 24px; }
}

const holes = Array.from(document.querySelectorAll('.hole'));
const scoreDisplay = document.querySelector('#score');
const timeDisplay = document.querySelector('#time');
const message = document.querySelector('#message');
const startButton = document.querySelector('#start');

let score = 0;
let timeLeft = 30;
let activeHole = -1;
let timerId = null;
let moleId = null;

function showRandomMole() {
  const next = Math.floor(Math.random() * holes.length);
  const chosen = next === activeHole ? (next + 1 + Math.floor(Math.random() * (holes.length - 1))) % holes.length : next;
  holes.forEach((hole, index) => hole.classList.toggle('active', index === chosen));
  activeHole = chosen;
}

function endGame() {
  clearInterval(timerId);
  clearInterval(moleId);
  timerId = null;
  moleId = null;
  activeHole = -1;
  holes.forEach(hole => hole.classList.remove('active'));
  message.textContent = `Game over! You scored ${score} ${score === 1 ? 'point' : 'points'}.`;
  startButton.disabled = false;
  startButton.textContent = 'Play again';
}

startButton.addEventListener('click', () => {
  if (timerId) return;
  score = 0;
  timeLeft = 30;
  scoreDisplay.textContent = score;
  timeDisplay.textContent = timeLeft;
  message.textContent = 'Quick! Click the mole!';
  startButton.disabled = true;
  startButton.textContent = 'Playing…';
  showRandomMole();
  moleId = setInterval(showRandomMole, 1000);
  timerId = setInterval(() => {
    timeLeft -= 1;
    timeDisplay.textContent = timeLeft;
    if (timeLeft <= 0) endGame();
  }, 1000);
});

holes.forEach((hole, index) => {
  hole.addEventListener('click', () => {
    if (timerId && index === activeHole) {
      score += 1;
      scoreDisplay.textContent = score;
      activeHole = -1;
      hole.classList.remove('active');
    }
  });
});
